\version "2.27.2"
% automatically converted by musicxml2ly from 41d-StaffGroups-Nested.xml
\pointAndClickOff

\header {
  texidoc = "Two properly nested part groups: One group (with a bracket) goes
    from staff 2 to 4, and another group (with a brace) goes from staff 3 to 4."
}
\layout {
  \context {
    \Staff
    printKeyCancellation = ##f
  }
  \context {
    \Score
    autoBeaming = ##f
  }
}
PartPOneVoiceOne = \relative b' {
  \clef "treble" \time 4/4 \key c \major b1 | % 1
  a1 | % 2
  R1 \bar "|."
}

PartPTwoVoiceOne = \relative a' {
  \clef "treble" \time 4/4 \key c \major a1 | % 1
  a1 | % 2
  R1 \bar "|."
}

PartPThreeVoiceOne = \relative a' {
  \clef "treble" \time 4/4 \key c \major a1 | % 1
  a1 | % 2
  R1 \bar "|."
}

PartPFourVoiceOne = \relative f' {
  \clef "treble" \time 4/4 \key c \major f1 | % 1
  b1 | % 2
  R1 \bar "|."
}

PartPFiveVoiceOne = \relative d'' {
  \clef "treble" \time 4/4 \key c \major d1 | % 1
  f,1 | % 2
  R1 \bar "|."
}


% The score definition
\score {
  <<
    \new Staff = "P1" <<
      \context Staff <<
        \override Staff.BarLine.allow-span-bar = ##f
        \mergeDifferentlyDottedOn
        \mergeDifferentlyHeadedOn
        \context Voice = "PartPOneVoiceOne" {
          \PartPOneVoiceOne
        }
      >>
    >>
    \new StaffGroup <<
      \new Staff = "P2" <<
        \context Staff <<
          \mergeDifferentlyDottedOn
          \mergeDifferentlyHeadedOn
          \context Voice = "PartPTwoVoiceOne" {
            \PartPTwoVoiceOne
          }
        >>
      >>
      \new StaffGroup \with {
        systemStartDelimiter = #'SystemStartBrace
      } <<
        \new Staff = "P3" <<
          \context Staff <<
            \mergeDifferentlyDottedOn
            \mergeDifferentlyHeadedOn
            \context Voice = "PartPThreeVoiceOne" {
              \PartPThreeVoiceOne
            }
          >>
        >>
        \new Staff = "P4" <<
          \context Staff <<
            \override Staff.BarLine.allow-span-bar = ##f
            \mergeDifferentlyDottedOn
            \mergeDifferentlyHeadedOn
            \context Voice = "PartPFourVoiceOne" {
              \PartPFourVoiceOne
            }
          >>
        >>
      >>
    >>
    \new Staff = "P5" <<
      \context Staff <<
        \override Staff.BarLine.allow-span-bar = ##f
        \mergeDifferentlyDottedOn
        \mergeDifferentlyHeadedOn
        \context Voice = "PartPFiveVoiceOne" {
          \PartPFiveVoiceOne
        }
      >>
    >>
  >>
  \layout {}
